const enc=new TextEncoder(),dec=new TextDecoder();
export function csvEncode(rows){return '\ufeff'+rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s)&&typeof v!=='number')s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n');}
export function csvParse(text){text=text.replace(/^\ufeff/,'');let rows=[],row=[],v='',q=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){v+='"';i++;}else if(!q&&v!=='')throw Error('Invalid CSV quoting.');else q=!q;}else if(c===','&&!q){row.push(v);v='';}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v);if(row.some(x=>x!==''))rows.push(row);row=[];v='';}else v+=c;}if(q)throw Error('Unclosed CSV quote.');row.push(v);if(row.some(x=>x!==''))rows.push(row);return rows;}
const xml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c])).replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,'');
const col=n=>{let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s;};
function crc32(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let j=0;j<8;j++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;}
function zip(files){let parts=[],central=[],offset=0;for(const [name,str] of Object.entries(files)){const n=enc.encode(name),b=enc.encode(str),crc=crc32(b);let h=new Uint8Array(30+n.length),d=new DataView(h.buffer);d.setUint32(0,0x04034b50,true);d.setUint16(4,20,true);d.setUint32(14,crc,true);d.setUint32(18,b.length,true);d.setUint32(22,b.length,true);d.setUint16(26,n.length,true);h.set(n,30);parts.push(h,b);let ch=new Uint8Array(46+n.length),cd=new DataView(ch.buffer);cd.setUint32(0,0x02014b50,true);cd.setUint16(4,20,true);cd.setUint16(6,20,true);cd.setUint32(16,crc,true);cd.setUint32(20,b.length,true);cd.setUint32(24,b.length,true);cd.setUint16(28,n.length,true);cd.setUint32(42,offset,true);ch.set(n,46);central.push(ch);offset+=h.length+b.length;}let e=new Uint8Array(22),ed=new DataView(e.buffer);ed.setUint32(0,0x06054b50,true);ed.setUint16(8,central.length,true);ed.setUint16(10,central.length,true);ed.setUint32(12,central.reduce((n,b)=>n+b.length,0),true);ed.setUint32(16,offset,true);return new Blob([...parts,...central,e],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});}
export function xlsxWrite(sheets){const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main';let files={'_rels/.rels':'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'};files['[Content_Types].xml']='<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'+sheets.map((s,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')+'</Types>';files['xl/workbook.xml']=`<workbook xmlns="${ns}" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>`+sheets.map((s,i)=>`<sheet name="${xml(s.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')+'</sheets></workbook>';files['xl/_rels/workbook.xml.rels']='<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+sheets.map((s,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')+'</Relationships>';for(const [i,s] of sheets.entries())files[`xl/worksheets/sheet${i+1}.xml`]=`<worksheet xmlns="${ns}"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="40" width="22" customWidth="1"/></cols><sheetData>`+s.rows.map((r,j)=>`<row r="${j+1}">`+r.map((v,k)=>typeof v==='number'&&Number.isFinite(v)?`<c r="${col(k)}${j+1}"><v>${v}</v></c>`:`<c r="${col(k)}${j+1}" t="inlineStr"><is><t xml:space="preserve">${xml(v)}</t></is></c>`).join('')+'</row>').join('')+'</sheetData></worksheet>';return zip(files);}
export async function unzip(buffer){let b=new Uint8Array(buffer),v=new DataView(buffer),end=-1;for(let i=b.length-22;i>=Math.max(0,b.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break;}if(end<0)throw Error('Not a valid XLSX file.');let count=v.getUint16(end+10,true),p=v.getUint32(end+16,true),out={},total=0;if(count>1000)throw Error('Workbook has too many parts.');for(let i=0;i<count;i++){if(v.getUint32(p,true)!==0x02014b50)throw Error('Invalid workbook archive.');const flags=v.getUint16(p+8,true),method=v.getUint16(p+10,true),size=v.getUint32(p+20,true),uncompressed=v.getUint32(p+24,true),nl=v.getUint16(p+28,true),el=v.getUint16(p+30,true),cl=v.getUint16(p+32,true),off=v.getUint32(p+42,true),name=dec.decode(b.slice(p+46,p+46+nl));total+=uncompressed;if(flags&1||total>30000000)throw Error('Encrypted or oversized workbook.');p+=46+nl+el+cl;if(!name.endsWith('.xml')&&!name.endsWith('.rels'))continue;const start=off+30+v.getUint16(off+26,true)+v.getUint16(off+28,true);let raw=b.slice(start,start+size);if(method===8){try{const reader=new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw')).getReader();let chunks=[],length=0;while(true){const part=await reader.read();if(part.done)break;length+=part.value.length;if(length>30000000){await reader.cancel();throw Error('Decompressed file is too large.');}chunks.push(part.value);}raw=new Uint8Array(length);let pos=0;for(const part of chunks){raw.set(part,pos);pos+=part.length;}}catch{throw Error('This browser cannot read compressed XLSX files. Import CSV instead.');}}else if(method!==0)throw Error('Unsupported workbook compression.');if(raw.length!==uncompressed)throw Error('Damaged workbook.');out[name]=dec.decode(raw);}return out;}
export async function xlsxRead(buffer){const files=await unzip(buffer);const parse=s=>{const x=new DOMParser().parseFromString(s??'','application/xml');if(x.querySelector('parsererror'))throw Error('Invalid workbook XML.');return x;};const w=parse(files['xl/workbook.xml']);const sheets=[...w.getElementsByTagName('sheet')];const sheet=sheets.find(s=>s.getAttribute('name')==='Trees')||sheets[0];if(!sheet)throw Error('No worksheet found.');const relId=sheet.getAttribute('r:id'),rel=[...parse(files['xl/_rels/workbook.xml.rels']).getElementsByTagName('Relationship')].find(r=>r.getAttribute('Id')===relId);if(!rel)throw Error('Worksheet link missing.');let target=rel.getAttribute('Target');const path=target.startsWith('/')?target.slice(1):'xl/'+target;const shared=files['xl/sharedStrings.xml']?[...parse(files['xl/sharedStrings.xml']).getElementsByTagName('si')].map(si=>[...si.getElementsByTagName('t')].map(t=>t.textContent).join('')):[];const rows=[];for(const row of parse(files[path]).getElementsByTagName('row')){let values=[];for(const cell of row.getElementsByTagName('c')){if(cell.getElementsByTagName('f').length)throw Error('Import values only: remove spreadsheet formulas from the Trees sheet.');const letters=(cell.getAttribute('r')||'A1').match(/^[A-Z]+/)[0];let index=0;for(const c of letters)index=index*26+c.charCodeAt(0)-64;let val=cell.getElementsByTagName('v')[0]?.textContent??'';if(cell.getAttribute('t')==='s')val=shared[Number(val)]??'';else if(cell.getAttribute('t')==='inlineStr')val=[...cell.getElementsByTagName('t')].map(t=>t.textContent).join('');values[index-1]=val;}if(values.some(v=>v!==''))rows.push(values);if(rows.length>1001)throw Error('Import at most 1,000 trees at a time.');}return rows;}
export function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
